 grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
 brain:'<path d="M12 5c-1-4-7-3-7 1-4 0-4 6-1 7-3 3 0 7 3 6 0 4 5 4 5 0V5Zm0 0c1-4 7-3 7 1 4 0 4 6 1 7 3 3 0 7-3 6 0 4-5 4-5 0V5Z"/><path d="M5 6c0 2 2 3 3 3m-4 4c2-2 5 0 4 2m-1 4c0-2 1-3 3-3m9-10c0 2-2 3-3 3m4 4c-2-2-5 0-4 2m1 4c0-2-1-3-3-3"/>',
