 layers:'<path d="m12 3 10 5-10 5L2 8l10-5Zm-10 9 10 5 10-5M2 16l10 5 10-5"/>',plug:'<path d="m7 3 3 3m7-3-3 3m-8 4 8 8 6-6-8-8-6 6Zm4 4-4 4c-2 2-4 2-4 4m16-4 3 3"/>',
 lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 5v2"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',
 bell:'<path d="M5 16h14l-2-3V9a5 5 0 0 0-10 0v4l-2 3Zm5 4h4m-2-19v2"/>',chevron:'<path d="m8 10 4 4 4-4"/>',right:'<path d="m9 5 7 7-7 7"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',upRight:'<path d="M6 18 18 6M6 6h12v12"/>',
 plus:'<path d="M12 5v14M5 12h14"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',check:'<path d="m5 12 4 4L19 6"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18m-12 4h2m4 0h2"/>',
 leaf:'<path d="M20 3C7 2 1 8 5 15s17 2 15-12Zm-1 1L5 19m5-7v-5m2 3h5"/>',code:'<path d="m8 7-5 5 5 5m8-10 5 5-5 5m-3-14-2 18"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Zm8-2v5m-2-2h5"/>',
 people:'<circle cx="9" cy="7" r="3"/><path d="M3 20v-3c0-5 12-5 12 0v3m0-16c5-1 6 6 1 7m2 3c3 0 4 2 4 5"/>',product:'<path d="m12 3 9 5v9l-9 5-9-5V8l9-5Zm0 0v9m0 0L3 8m9 4 9-4m-9 4v10"/>',
 sales:'<path d="M4 21V10h4v11m4 0V4h4v17m4 0V14h3v7M2 21h21"/>',finance:'<circle cx="12" cy="12" r="9"/><path d="M15 8c-5-3-8 3-3 4s2 7-3 4m3-11v14"/>',marketing:'<path d="m3 10 16-6v14L3 13v-3Zm4 4 1 6h4l-2-5m12-7 1-1m-1 8 1 1"/>',
 file:'<path d="M14 3H5v18h14V8l-5-5Zm0 0v5h5M8 12h8m-8 4h6"/>',task:'<rect x="4" y="4" width="16" height="17" rx="2"/><path d="M8 2h8v4H8V2Zm0 11 2 2 5-5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',
